"""Bulk pricing rules (see README.md)."""


def unit_price_cents(quantity: int, base_cents: int) -> int:
    if quantity <= 0:
        raise ValueError("quantity must be positive")
    if quantity > 100:
        return base_cents * 80 // 100
    if quantity >= 10:
        return base_cents * 90 // 100
    return base_cents

