import pytest

from pricing import unit_price_cents


def test_no_discount_below_10_units():
    assert unit_price_cents(9, 1000) == 1000


def test_ten_percent_from_10_units():
    assert unit_price_cents(10, 1000) == 900


def test_bulk_discount_at_100_units():
    assert unit_price_cents(100, 1000) == 800


def test_rejects_zero_quantity():
    with pytest.raises(ValueError):
        unit_price_cents(0, 1000)
